387	     * i.e. one sharing its computed {@link Owner#getHouseholdId() householdId} (derived from last name
388	     * and postcode). Because the household is keyed on (last name, postcode), such an owner is a
389	     * household duplicate of the new one. Owners flagged {@link Owner#isDeleted() deleted} are ignored.
390	     * Returns the first such owner, or {@code null} when the owner has no household
391	     * ({@code householdId} is null) or no match exists.
392	     */
393	    @Override
394	    @Transactional(readOnly = true)
395	    public Owner findHouseholdDuplicateOf(Owner owner) throws DataAccessException {
396	        String householdId = owner.getHouseholdId();
397	        if (householdId == null) {
398	            return null;
399	        }
400	        return ownerRepository.findAll().stream()
401	            .filter(existing -> !existing.isDeleted())
402	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
403	            .findFirst()
404	            .orElse(null);
405	    }
