575	     * Return the Pet with the given name, or null if none found for this Owner.
576	     *
577	     * @param name to test
578	     * @return true if pet name is already in use
579	     */
580	    public Pet getPet(String name, boolean ignoreNew) {
581	        name = name.toLowerCase();
582	        for (Pet pet : getPetsInternal()) {
583	            if (!ignoreNew || !pet.isNew()) {
584	                String compName = pet.getName();
585	                compName = compName.toLowerCase();
586	                if (compName.equals(name)) {
587	                    return pet;
588	                }
589	            }
590	        }
591	        return null;
592	    }
