16	package org.springframework.samples.petclinic.service;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Locale;
22	
23	/**
24	 * Computes upper-case hexadecimal SHA-256 digests. Shared by the identifier generators
25	 * so the digest-to-hex logic lives in exactly one place.
26	 */
27	public final class Sha256Hex {
28	
29	    private Sha256Hex() {
30	    }
31	
32	    /**
33	     * Digest {@code input} with SHA-256 and return the first {@code length} characters of its
34	     * hexadecimal representation, upper-cased.
35	     *
36	     * @param input  the string whose UTF-8 bytes are digested
37	     * @param length the number of leading hex characters to return
38	     * @return the upper-case hexadecimal prefix of the digest
39	     */
40	    public static String upperHexPrefix(String input, int length) {
41	        return fullHex(input).substring(0, length).toUpperCase(Locale.ROOT);
42	    }
43	
44	    private static String fullHex(String input) {
45	        try {
46	            byte[] digest = MessageDigest.getInstance("SHA-256")
47	                .digest(input.getBytes(StandardCharsets.UTF_8));
48	            StringBuilder hex = new StringBuilder(digest.length * 2);
49	            for (byte b : digest) {
50	                hex.append(String.format("%02x", b));
51	            }
52	            return hex.toString();
53	        }
54	        catch (NoSuchAlgorithmException e) {
55	            throw new IllegalStateException("SHA-256 is required for identifier generation", e);
56	        }
57	    }
58	}
