17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
30	import org.springframework.samples.petclinic.rest.controller.BusinessDayResolver;
31	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerIdentityException;
32	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
33	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
34	import org.springframework.samples.petclinic.rest.controller.IdempotencyKeyRegistry;
35	import org.springframework.samples.petclinic.rest.controller.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
37	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.PostcodeValidator;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.samples.petclinic.service.HouseholdIdGenerator;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final PostcodeValidator postcodeValidator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final BusinessDayResolver businessDayResolver;
89	
90	    private final OwnerAuditLogger ownerAuditLogger;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
95	
96	    /** Maximum number of owners a single city may hold before further creations are rejected. */
97	    static final long MAX_OWNERS_PER_CITY = 50;
98	
99	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
100	    static final long MAX_OWNERS_PER_DAY = 100;
101	
102	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
103	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper,
109	                                 OwnerFieldsValidator ownerFieldsValidator,
110	                                 PostcodeValidator postcodeValidator,
111	                                 TelephoneNormalizer telephoneNormalizer,
112	                                 EmailNormalizer emailNormalizer,
113	                                 AddressNormalizer addressNormalizer,
114	                                 BusinessDayResolver businessDayResolver,
115	                                 OwnerAuditLogger ownerAuditLogger,
116	                                 HouseholdIdGenerator householdIdGenerator,
117	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	        this.ownerFieldsValidator = ownerFieldsValidator;
123	        this.postcodeValidator = postcodeValidator;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.emailNormalizer = emailNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.businessDayResolver = businessDayResolver;
128	        this.ownerAuditLogger = ownerAuditLogger;
129	        this.householdIdGenerator = householdIdGenerator;
130	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
161	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
162	        if (existingOwnerId != null) {
163	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
164	            if (existingOwner != null) {
165	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
166	            }
167	        }
168	        this.normalizeAddress(ownerFieldsDto);
169	        this.ownerFieldsValidator.validate(ownerFieldsDto);
170	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
175	        LocalDate serverDate = LocalDate.now();
176	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
177	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
178	        }
179	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
180	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
181	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
182	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
183	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
184	        }
185	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
186	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
188	        }
189	        if (owner.getPostcode() != null) {
190	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
191	        }
192	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
193	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
194	        }
195	        this.clinicService.saveOwner(owner);
196	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
197	        this.ownerAuditLogger.logCreated(owner);
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        headers.setLocation(UriComponentsBuilder.newInstance()
200	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
201	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    /**
205	     * Canonicalize the request's address fields in place, preferring the structured form. When a
206	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
207	     * normalized and the composed value stored on {@code address}; otherwise only the flat
208	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
209	     * value everything downstream reads.
210	     */
211	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
212	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
213	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
214	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
215	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
216	            ownerFieldsDto.setAddress(
217	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
218	        }
219	        else {
220	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
221	        }
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner == null) {
229	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	        }
231	        currentOwner.setAddress(ownerFieldsDto.getAddress());
232	        currentOwner.setCity(ownerFieldsDto.getCity());
233	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
234	        currentOwner.setLastName(ownerFieldsDto.getLastName());
235	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
236	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
237	        this.clinicService.saveOwner(currentOwner);
238	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Transactional
243	    @Override
244	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        this.clinicService.deleteOwner(owner);
250	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        HttpHeaders headers = new HttpHeaders();
261	        Pet pet = petMapper.toPet(petFieldsDto);
262	        owner.setId(ownerId);
263	        pet.setOwner(owner);
264	        pet.getType().setName(null);
265	        this.clinicService.savePet(pet);
266	        PetDto petDto = petMapper.toPetDto(pet);
267	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
268	            .buildAndExpand(pet.getId()).toUri());
269	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
275	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
276	        if (currentOwner != null) {
277	            Pet currentPet = this.clinicService.findPetById(petId);
278	            if (currentPet != null) {
279	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
280	                currentPet.setName(petFieldsDto.getName());
281	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
282	                this.clinicService.savePet(currentPet);
283	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
284	            }
285	        }
286	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
292	        HttpHeaders headers = new HttpHeaders();
293	        Visit visit = visitMapper.toVisit(visitFieldsDto);
294	        Pet pet = new Pet();
295	        pet.setId(petId);
296	        visit.setPet(pet);
297	        this.clinicService.saveVisit(visit);
298	        VisitDto visitDto = visitMapper.toVisitDto(visit);
299	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
300	            .buildAndExpand(visit.getId()).toUri());
301	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
302	    }
303	
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
308	        Owner owner = this.clinicService.findOwnerById(ownerId);
309	        if (owner != null) {
310	            Pet pet = owner.getPet(petId);
311	            if (pet != null) {
312	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
313	            }
314	        }
315	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	    }
317	}
