242	    @Override
243	    @Transactional
244	    public void saveOwner(Owner owner) throws DataAccessException {
245	        if (owner.isNew() && owner.getCustomerCode() == null) {
246	            String region = LocalityResolver.regionFor(owner.getPostcode(), owner.getCity());
247	            String customerCode =
248	                customerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
249	            owner.setCustomerCode(deduplicateCustomerCode(customerCode));
250	        }
251	        if (owner.isNew() && owner.getNamesakeCount() == null) {
252	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
253	        }
254	        if (owner.isNew() && owner.getMembershipNumber() == null) {
255	            owner.setMembershipNumber(
256	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
257	        }
258	        if (owner.isNew() && owner.getHouseholdSize() == null) {
259	            owner.setHouseholdSize(countHouseholdMembers(owner));
260	        }
261	        if (owner.isNew() && owner.getMembershipLevelCap() == null) {
262	            owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
263	        }
264	        ownerRepository.save(owner);
265	    }
266	
267	    /**
268	     * Count the members of the given (not yet persisted) owner's household: the already stored
269	     * owners sharing its {@code householdId} plus the owner itself. An owner with no household
270	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
271	     * size at creation time.
272	     */
273	    private int countHouseholdMembers(Owner owner) {
274	        String householdId = owner.getHouseholdId();
275	        if (householdId == null) {
276	            return 1;
277	        }
278	        long existing = ownerRepository.findAll().stream()
279	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
280	            .count();
281	        return (int) (existing + 1);
282	    }
283	
284	    /**
285	     * Determine the membership-level ceiling for the given (not yet persisted) owner: one above the
286	     * highest {@link Owner#getMembershipLevel() membership level} among the already stored,
287	     * non-deleted members of its household (owners sharing its {@code householdId}). Returns
288	     * {@code null} when the owner has no household ({@code householdId} is null) or no existing
289	     * household member, in which case no ceiling applies. Used to cap an owner's membership level
290	     * at creation time.
291	     */
292	    private Integer computeMembershipLevelCap(Owner owner) {
293	        String householdId = owner.getHouseholdId();
294	        if (householdId == null) {
295	            return null;
296	        }
297	        OptionalInt maxLevel = ownerRepository.findAll().stream()
298	            .filter(existing -> !existing.isDeleted())
299	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
300	            .mapToInt(Owner::getMembershipLevel)
301	            .max();
302	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
303	    }
304	
305	    /**
306	     * Count the owners already stored in the given city, compared case-insensitively. Used to
307	     * enforce the per-city capacity limit at creation time.
308	     */
309	    @Override
310	    @Transactional(readOnly = true)
311	    public long countOwnersInCity(String city) throws DataAccessException {
312	        return ownerRepository.findAll().stream()
313	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
314	            .count();
315	    }
316	
317	    /**
318	     * Count the owners already stored whose registration date equals the given date. Used to
319	     * enforce the per-day registration limit at creation time.
320	     */
321	    @Override
322	    @Transactional(readOnly = true)
323	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
324	        return ownerRepository.findAll().stream()
325	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
326	            .count();
327	    }
328	
329	    /**
330	     * Count the owners already stored that share the given first and last name, compared
331	     * case-insensitively. Used to capture an owner's namesake count at creation time.
332	     */
333	    private int countNamesakes(String firstName, String lastName) {
334	        return (int) ownerRepository.findAll().stream()
335	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
336	                && equalsIgnoreCase(existing.getLastName(), lastName))
337	            .count();
338	    }
339	
340	    /**
341	     * Ensure the given customer code does not collide with an already stored owner's. When it does,
342	     * append {@code -<n>} using the smallest {@code n} of 2 or more that makes it unique. Used to
343	     * guarantee that distinct owners always receive distinct customer codes at creation time.
344	     */
345	    private String deduplicateCustomerCode(String customerCode) {
346	        Set<String> existing = ownerRepository.findAll().stream()
347	            .map(Owner::getCustomerCode)
